// ============================================================
// Keystone PT Script  -  Generated by Keystone Automation
//
// HOW TO USE
//   1. Open Packet Tracer
//   2. Place ONE seed device on the canvas for each type below:
//        - One 2911  (router)
//   3. Extensions  ->  Scripting  ->  Edit File Script Module
//   4. Load this file and click  Run
//   5. Manually cable the connections shown in the console output
//   6. Delete the original seed device(s) from the canvas
//   7. File  ->  Save As  ->  your_lab.pkt
//
// Topology: 5 device(s), 0 connection(s)
// ============================================================

function main()
{
    dprint("=== KEYSTONE TOPOLOGY BUILDER ===");
    dprint("");

    try {

        var network    = ipc.network();
        var activeFile = ipc.appWindow().getActiveFile();

        dprint("Seed devices on canvas: " + network.getDeviceCount());

        // ===== PHASE 1: LOCATE SEED DEVICES =====
        dprint("[1/4] Locating seed devices...");
        var seeds = {};
        for (var i = 0; i < network.getDeviceCount(); i++) {
            var d     = network.getDeviceAt(i);
            var model = d.getModel();
            if (!seeds[model]) {
                seeds[model] = d;
                dprint("  OK  Found seed: " + model + " (" + d.getName() + ")");
            }
        }

        if (!seeds["2911"]) {
            dprint("  ERR  Missing seed: 2911");
            dprint("       Add one router (2911) to the canvas and re-run.");
            return;
        }

        // ===== PHASE 2: CREATE DEVICES =====
        dprint("[2/4] Creating devices...");
        var devs = {};

        // --- CORE-R1 ---
        activeFile.duplicateDevice(seeds["2911"]);
        var dev_CORE_R1 = network.getDeviceAt(network.getDeviceCount() - 1);
        dev_CORE_R1.moveToLocationCentered(120, 120);
        devs["CORE-R1"] = dev_CORE_R1;
        dprint("  +  CORE-R1 at (120, 120)");
        java.lang.Thread.sleep(300);

        // --- EDGE-R2 ---
        activeFile.duplicateDevice(seeds["2911"]);
        var dev_EDGE_R2 = network.getDeviceAt(network.getDeviceCount() - 1);
        dev_EDGE_R2.moveToLocationCentered(340, 120);
        devs["EDGE-R2"] = dev_EDGE_R2;
        dprint("  +  EDGE-R2 at (340, 120)");
        java.lang.Thread.sleep(300);

        // --- DHCP-R3 ---
        activeFile.duplicateDevice(seeds["2911"]);
        var dev_DHCP_R3 = network.getDeviceAt(network.getDeviceCount() - 1);
        dev_DHCP_R3.moveToLocationCentered(560, 120);
        devs["DHCP-R3"] = dev_DHCP_R3;
        dprint("  +  DHCP-R3 at (560, 120)");
        java.lang.Thread.sleep(300);

        // --- REDUNDANCY-R4 ---
        activeFile.duplicateDevice(seeds["2911"]);
        var dev_REDUNDANCY_R4 = network.getDeviceAt(network.getDeviceCount() - 1);
        dev_REDUNDANCY_R4.moveToLocationCentered(780, 120);
        devs["REDUNDANCY-R4"] = dev_REDUNDANCY_R4;
        dprint("  +  REDUNDANCY-R4 at (780, 120)");
        java.lang.Thread.sleep(300);

        // --- NAT-GATEWAY ---
        activeFile.duplicateDevice(seeds["2911"]);
        var dev_NAT_GATEWAY = network.getDeviceAt(network.getDeviceCount() - 1);
        dev_NAT_GATEWAY.moveToLocationCentered(1000, 120);
        devs["NAT-GATEWAY"] = dev_NAT_GATEWAY;
        dprint("  +  NAT-GATEWAY at (1000, 120)");
        java.lang.Thread.sleep(300);

        // ===== PHASE 3: CONNECTIONS (manual cabling required) =====
        dprint("[3/4] Connections to cable manually:");
        dprint("  (no connections defined in topology)");

        // ===== PHASE 4: CONFIGURE DEVICES =====
        dprint("[4/4] Configuring devices (this may take a moment)...");

        dprint("  >> CORE-R1");
        configureDevice(devs["CORE-R1"], ["enable", "configure terminal", "hostname CORE-R1", "interface GigabitEthernet0/0/0", " description Link to EDGE-R2", " ip address 10.0.1.1 255.255.255.0", " no shutdown", " exit", "interface GigabitEthernet0/0/1", " description Link to DHCP-R3", " ip address 10.0.2.1 255.255.255.0", " no shutdown", " exit", "router ospf 1", " router-id 1.1.1.1", " network 10.0.1.0 0.0.0.255 area 0", " network 10.0.2.0 0.0.0.255 area 0", " exit", "ip domain-name lab.local", "crypto key generate rsa modulus 1024", "line vty 0 4", " transport input ssh", " exit", "end", "write memory"]);
        java.lang.Thread.sleep(500);

        dprint("  >> EDGE-R2");
        configureDevice(devs["EDGE-R2"], ["enable", "configure terminal", "hostname EDGE-R2", "interface GigabitEthernet0/0/0", " description Link to CORE-R1", " ip address 10.0.1.2 255.255.255.0", " no shutdown", " exit", "interface GigabitEthernet0/0/1", " description WAN to ISP", " ip address 192.168.1.1 255.255.255.0", " no shutdown", " exit", "router ospf 1", " router-id 2.2.2.2", " network 10.0.1.0 0.0.0.255 area 0", " exit", "router bgp 65100", " bgp router-id 2.2.2.2", " neighbor 192.168.1.254 remote-as 65001", " neighbor 192.168.1.254 description ISP Connection", " network 10.0.0.0 mask 255.255.0.0", " exit", "end", "write memory"]);
        java.lang.Thread.sleep(500);

        dprint("  >> DHCP-R3");
        configureDevice(devs["DHCP-R3"], ["enable", "configure terminal", "hostname DHCP-R3", "interface GigabitEthernet0/0/0", " description Link to CORE-R1", " ip address 10.0.2.2 255.255.255.0", " no shutdown", " exit", "interface GigabitEthernet0/0/1", " description Internal LAN", " ip address 10.0.3.1 255.255.255.0", " no shutdown", " exit", "router ospf 1", " router-id 3.3.3.3", " network 10.0.2.0 0.0.0.255 area 0", " network 10.0.3.0 0.0.0.255 area 0", " exit", "ip dhcp pool LAN-POOL", " network 10.0.3.0 255.255.255.0", " default-router 10.0.3.1", " dns-server 8.8.8.8", " exit", "ip dhcp excluded-address 10.0.3.1 10.0.3.10", "end", "write memory"]);
        java.lang.Thread.sleep(500);

        dprint("  >> REDUNDANCY-R4");
        configureDevice(devs["REDUNDANCY-R4"], ["enable", "configure terminal", "hostname REDUNDANCY-R4", "interface GigabitEthernet0/0/0", " description Link to CORE-R1", " ip address 10.0.2.3 255.255.255.0", " no shutdown", " exit", "interface vlan 10", " description Management VLAN", " ip address 10.0.10.254 255.255.255.0", " no shutdown", " exit", "router ospf 1", " router-id 4.4.4.4", " network 10.0.2.0 0.0.0.255 area 0", " network 10.0.10.0 0.0.0.255 area 0", " exit", "interface vlan 10", " standby 1 ip 10.0.10.1", " standby 1 priority 110", " standby 1 preempt", " no shutdown", " exit", "end", "write memory"]);
        java.lang.Thread.sleep(500);

        dprint("  >> NAT-GATEWAY");
        configureDevice(devs["NAT-GATEWAY"], ["enable", "configure terminal", "hostname NAT-GATEWAY", "interface GigabitEthernet0/0/0", " description Inside network", " ip address 10.0.1.254 255.255.255.0", " no shutdown", " exit", "interface GigabitEthernet0/0/1", " description Outside (Internet)", " ip address 203.0.113.50 255.255.255.0", " no shutdown", " exit", "interface GigabitEthernet0/0/0", " ip nat inside", " exit", "interface GigabitEthernet0/0/1", " ip nat outside", " exit", "ip nat inside source static 10.0.3.50 203.0.113.100", "ip nat pool INTERNET-POOL 203.0.113.200 203.0.113.220 netmask 255.255.255.0", "ip route 10.0.0.0 255.255.0.0 10.0.1.1", "end", "write memory"]);
        java.lang.Thread.sleep(500);

        dprint("");
        dprint("=== TOPOLOGY COMPLETE ===");
        dprint("  Devices created : 5");
        dprint("  Connections     : 0 (see above for cabling)");
        dprint("");
        dprint("Next steps:");
        dprint("  1. Cable the connections listed above");
        dprint("  2. Delete the original seed device(s)");
        dprint("  3. File -> Save As -> your_lab.pkt");

    } catch(e) {
        dprint("FATAL ERROR: " + e.message);
        dprint(e.stack);
    }
}


// ============================================================
// Helper: send a list of IOS CLI commands to a device
// ============================================================
function configureDevice(device, commands)
{
    try {
        var cli = device.getCommandLine();
        if (cli == null) {
            dprint("  WARN  No CLI available for " + device.getName());
            return;
        }

        // Dismiss the initial configuration dialog if it appears
        var initialOut = cli.getOutput();
        if (initialOut.indexOf("initial configuration dialog") > -1) {
            cli.enterCommand("no");
            java.lang.Thread.sleep(500);
        }

        // Send each command with a short delay
        for (var i = 0; i < commands.length; i++) {
            cli.enterCommand(commands[i]);
            java.lang.Thread.sleep(100);
        }

        dprint("  OK  " + device.getName());

    } catch(e) {
        dprint("  ERR  " + device.getName() + ": " + e.message);
    }
}


function cleanUp()
{
    dprint("Script cleanup complete.");
}
